<template>
    <section class="kw-map">
        <template v-if="kind === 'graph'"><div class="kw-row"><label>图谱范围<select v-model="scope" class="input"><option value="global">全局关系图</option><option value="local">当前笔记的一跳关系</option></select></label><input v-model="search" class="input" type="search" placeholder="筛选图谱中的笔记" aria-label="图谱筛选" /><button class="btn btn-sm" @click="zoom = Math.min(2, zoom + .2)">放大</button><button class="btn btn-sm" @click="zoom = Math.max(.4, zoom - .2)">缩小</button><button class="btn btn-sm" @click="zoom=1">复位</button></div><p class="kw-muted">{{ graphNotes.length }}个节点 · 点击打开笔记；显示前100个匹配节点，未显示的笔记仍可在快速切换中查找。</p><svg class="kw-graph" :viewBox="`${500-500/zoom} ${300-300/zoom} ${1000/zoom} ${600/zoom}`" aria-label="笔记关系图"><line v-for="(edge,i) in graphEdges" :key="i" :x1="point(edge.from).x" :y1="point(edge.from).y" :x2="point(edge.to).x" :y2="point(edge.to).y" /><g v-for="note in graphNotes" :key="note.id" :transform="`translate(${point(note.id).x},${point(note.id).y})`" tabindex="0" role="button" :aria-label="note.title" @click="$emit('open',note.id)" @keydown.enter="$emit('open',note.id)" @keydown.space.prevent="$emit('open',note.id)"><circle :r="note.id===currentId?12:8" :class="{'is-current':note.id===currentId}" /><text y="24" text-anchor="middle">{{ note.title.slice(0,14) }}</text><title>{{ note.path }}</title></g></svg><p v-if="!graphNotes.length" class="kw-empty">没有匹配节点；局部图谱需要先打开一篇笔记。</p></template>
        <template v-else><div class="kw-row"><label>知识画布<select :value="selected" class="input" @change="changeSelection($event.target)"><option value="">新画布</option><option v-for="item in canvases" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><input v-model="draft.name" class="input" aria-label="画布名称" maxlength="80" /><button class="btn" @click="newCanvas">新建</button><button id="kw-canvas-save" class="btn btn-primary" :disabled="busy" @click="save">保存画布</button><button v-if="selected" class="btn btn-danger" :disabled="busy" @click="remove">删除画布</button></div><p v-if="error" class="workshop-error" role="alert">{{ error }}</p><p v-if="notice" class="workshop-success" role="status">{{ notice }}</p>
            <div class="kw-row"><select v-model="nodeNote" class="input" aria-label="要加入画布的笔记"><option v-for="note in notes" :key="note.id" :value="note.id">{{ note.title }}</option></select><button class="btn btn-sm" :disabled="!nodeNote" @click="addNode('note')">添加笔记节点</button><input v-model="nodeText" class="input" maxlength="2000" aria-label="文字节点内容" placeholder="文字卡片内容" /><button class="btn btn-sm" :disabled="!nodeText.trim()" @click="addNode('text')">添加文字节点</button></div>
            <div class="kw-row"><select v-model="from" class="input" aria-label="连接起点"><option value="">连接起点</option><option v-for="node in draft.data.nodes" :key="node.id" :value="node.id">{{ label(node).slice(0,30) }}</option></select><select v-model="to" class="input" aria-label="连接终点"><option value="">连接终点</option><option v-for="node in draft.data.nodes" :key="node.id" :value="node.id">{{ label(node).slice(0,30) }}</option></select><button class="btn btn-sm" :disabled="!from||!to||from===to" @click="connect">连接</button><button class="btn btn-sm" :disabled="!chosen" @click="removeNode">删除选中节点</button></div>
            <p class="kw-muted">拖动节点或聚焦后按方向键移动（Shift加速），双击笔记节点打开。位置与连线点击保存后保留；删除节点不删除原笔记。</p>
            <svg ref="canvas" class="kw-canvas" viewBox="0 0 1200 800" aria-label="知识画布" @pointermove="move" @pointerup="endDrag" @pointercancel="endDrag" @lostpointercapture="endDrag"><line v-for="(edge,i) in draft.data.edges" :key="i" :x1="nodePoint(edge.from).x+85" :y1="nodePoint(edge.from).y+35" :x2="nodePoint(edge.to).x+85" :y2="nodePoint(edge.to).y+35" /><g v-for="node in draft.data.nodes" :key="node.id" :transform="`translate(${node.x},${node.y})`" role="button" tabindex="0" :aria-label="label(node)" :class="{'is-chosen':chosen===node.id}" @pointerdown="startDrag($event,node)" @dblclick="node.type==='note'&&$emit('open',node.docId)" @keydown="keyMove($event,node)"><rect width="170" height="76" rx="10" /><text x="12" y="25">{{ node.type==='note'?'笔记':'文字' }}</text><text x="12" y="52">{{ label(node).slice(0,14) }}</text><title>{{ label(node) }}</title></g></svg>
            <div v-if="chosenNode?.type==='text'" class="kw-row"><label>选中文字节点内容<textarea v-model="chosenNode.text" class="input" maxlength="2000" /></label></div><details class="kw-details"><summary>连接 {{ draft.data.edges.length }}条</summary><div v-for="(edge,i) in draft.data.edges" :key="i" class="kw-row"><span>{{ label(nodePoint(edge.from)) }} → {{ label(nodePoint(edge.to)) }}</span><button class="btn btn-sm" @click="draft.data.edges.splice(i,1)">移除连接</button></div></details>
        </template>
    </section>
</template>
<script setup>
import { ref,computed,watch,onBeforeUnmount } from 'vue';
import { kbApi } from '../../api/knowledge-workbench-client.js';
const props=defineProps({kind:String,entries:Array,notes:Array,edges:Array,currentId:Number}),emit=defineEmits(['open','changed']);
const clone=value=>JSON.parse(JSON.stringify(value)),scope=ref('global'),search=ref(''),zoom=ref(1),canvases=computed(()=>props.entries.filter(e=>e.kind==='canvas')),selected=ref(''),draft=ref(blank()),nodeNote=ref(props.currentId||props.notes[0]?.id),nodeText=ref(''),from=ref(''),to=ref(''),chosen=ref(''),canvas=ref(null),busy=ref(false),error=ref(''),notice=ref('');
function blank(){return{kind:'canvas',name:'新知识画布',data:{nodes:[],edges:[]}};}
const graphNotes=computed(()=>{const linked=new Set([props.currentId]);for(const edge of props.edges)if(edge.from===props.currentId||edge.to===props.currentId){linked.add(edge.from);linked.add(edge.to);}return props.notes.filter(n=>(scope.value==='global'||linked.has(n.id))&&n.path.toLocaleLowerCase().includes(search.value.toLocaleLowerCase())).slice(0,100);}),graphEdges=computed(()=>{const ids=new Set(graphNotes.value.map(n=>n.id));return props.edges.filter(e=>ids.has(e.from)&&ids.has(e.to));}),points=computed(()=>new Map(graphNotes.value.map((n,i)=>{const ring=Math.floor(i/25),count=Math.min(25,graphNotes.value.length-ring*25),angle=(i%25)/count*Math.PI*2,radius=graphNotes.value.length===1?0:80+ring*65;return[n.id,{x:500+Math.cos(angle)*radius*1.6,y:280+Math.sin(angle)*radius}];}))),chosenNode=computed(()=>draft.value.data.nodes.find(n=>n.id===chosen.value));
function point(id){return points.value.get(id)||{x:500,y:300};}function nodePoint(id){return draft.value.data.nodes.find(n=>n.id===id)||{x:0,y:0,text:'失效节点'};}function label(node){return node.type==='note'?props.notes.find(n=>n.id===node.docId)?.title||`失效笔记 #${node.docId}`:node.text||'';}
let alive=true,controller=new AbortController(),drag=null,baseline='';
function dirty(){return props.kind==='canvas'&&baseline!==JSON.stringify(draft.value);}function canLeave(){return !busy.value&&(!dirty()||confirm('知识画布有未保存修改，离开会丢弃。继续？'));}
function loadCanvas(){const item=canvases.value.find(c=>c.id===selected.value);draft.value=item?clone(item):blank();chosen.value='';baseline=JSON.stringify(draft.value);}
function changeSelection(selectElement){if(!canLeave()){selectElement.value=selected.value;return;}selected.value=selectElement.value;loadCanvas();}
function newCanvas(){if(!canLeave())return;selected.value='';loadCanvas();}
watch(()=>canvases.value.map(c=>c.id+':'+c.version).join(','),()=>{if(baseline&&dirty())return;if(!selected.value&&canvases.value.length)selected.value=canvases.value[0].id;loadCanvas();},{immediate:true});
function addNode(type){if(draft.value.data.nodes.length>=100){error.value='每张画布最多100个节点';return;}const i=draft.value.data.nodes.length;draft.value.data.nodes.push({id:crypto.randomUUID(),type,...(type==='note'?{docId:Number(nodeNote.value)}:{text:nodeText.value}),x:30+(i%5)*220,y:30+Math.floor(i/5)*100});}
function connect(){if(!draft.value.data.edges.some(e=>e.from===from.value&&e.to===to.value))draft.value.data.edges.push({from:from.value,to:to.value});}
function removeNode(){if(!confirm('删除此画布节点及其连线？原笔记保留。'))return;draft.value.data.nodes=draft.value.data.nodes.filter(n=>n.id!==chosen.value);draft.value.data.edges=draft.value.data.edges.filter(e=>e.from!==chosen.value&&e.to!==chosen.value);chosen.value='';}
function position(event){const svg=canvas.value,point=new DOMPoint(event.clientX,event.clientY);return point.matrixTransform(svg.getScreenCTM().inverse());}
function startDrag(event,node){if(event.button!==0)return;event.preventDefault();chosen.value=node.id;const point=position(event);drag={id:node.id,x:point.x-node.x,y:point.y-node.y};canvas.value.setPointerCapture(event.pointerId);event.currentTarget.focus();}
function move(event){if(!drag)return;const point=position(event),node=nodePoint(drag.id);node.x=Math.max(0,Math.min(1030,Math.round(point.x-drag.x)));node.y=Math.max(0,Math.min(724,Math.round(point.y-drag.y)));}
function endDrag(){drag=null;}function keyMove(event,node){const direction={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[event.key];if(!direction)return;event.preventDefault();chosen.value=node.id;const step=event.shiftKey?20:5;node.x=Math.max(0,Math.min(1030,node.x+direction[0]*step));node.y=Math.max(0,Math.min(724,node.y+direction[1]*step));}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const result=await kbApi.saveEntry(draft.value,controller.signal);if(alive){selected.value=result.id;draft.value=result;baseline=JSON.stringify(result);notice.value='画布已保存';emit('changed');}}catch(failure){if(alive&&!controller.signal.aborted)error.value=failure.message;}finally{if(alive)busy.value=false;}}
async function remove(){if(!confirm('永久删除此知识画布？笔记保留。'))return;busy.value=true;try{await kbApi.remove(draft.value,controller.signal);if(alive){selected.value='';loadCanvas();emit('changed');}}catch(failure){if(alive)error.value=failure.message;}finally{if(alive)busy.value=false;}}
onBeforeUnmount(()=>{alive=false;controller.abort();drag=null;});defineExpose({canLeave,hasUnsaved:dirty});
</script>
